import{_ as d,c as t,e as s,o as v}from"./index-DUl6PKBW.js";const r={name:"ConferencePage"},f={class:"container py-5"};function o(l,a,c,i,e,n){return v(),t("div",f,a[0]||(a[0]=[s('<h1 class="text-center mb-4" data-v-d801f092> Ежегодная научно-образовательная конференция<br data-v-d801f092><small class="text-muted" data-v-d801f092>&quot;Неврологические образовательные университеты&quot;</small></h1><p data-v-d801f092> Уже на протяжении более 20 лет проводится ежегодная конференция. В программу включаются различные актуальные вопросы неврологии и смежных специальностей, акцентируя внимание на новые направления и междисциплинарное взаимодействие. </p><div class="alert alert-info mt-4" data-v-d801f092><strong data-v-d801f092>Годы проведения: </strong><a href="#" class="link-primary text-decoration-none" data-v-d801f092>2016</a>, <a href="/educational/2017" class="link-primary text-decoration-none" data-v-d801f092>2017</a>, <a href="/educational/2018" class="link-primary text-decoration-none" data-v-d801f092>2018</a></div><div class="card my-5" data-v-d801f092><div class="card-body" data-v-d801f092><h5 class="card-title" data-v-d801f092>Формат конференции 2018 года</h5><p class="card-text" data-v-d801f092> Впервые конференция прошла в формате междисциплинарного взаимодействия неврологов и нейрохирургов под руководством профессора Владимира Ивановича Шмырева и д.м.н. Ольги Бенуаовны Белоусовой. Рассматривались темы боли и сосудистых нарушений, принципы диагностики, современные методы лечения и реабилитации. </p></div></div><h4 data-v-d801f092>Особое внимание:</h4><ul data-v-d801f092><li data-v-d801f092>Неинвазивные и малоинвазивные методы лечения.</li><li data-v-d801f092>Алгология в неврологии.</li><li data-v-d801f092>Нейрохирургия и нейрореабилитация.</li><li data-v-d801f092>Проблемы сосудистой неврологии.</li></ul><p class="mt-4" data-v-d801f092> Докладчик от французской школы — <strong data-v-d801f092>Серж Лашер</strong>, эксперт по KISS-синдрому, представил доклад, вызвавший большой интерес. </p><div class="card my-5" data-v-d801f092><div class="card-body" data-v-d801f092><h5 class="card-title" data-v-d801f092>Мастер-класс</h5><p class="card-text" data-v-d801f092> &quot;Миофасциальные и биомеханические нарушения в клинической практике&quot; провёл доцент Алексей Сергеевич Васильев. </p></div></div><div class="card my-5" data-v-d801f092><div class="card-body" data-v-d801f092><h5 class="card-title" data-v-d801f092>11 апреля 2017 года</h5><p class="card-text" data-v-d801f092> В рамках Ежегодных научно-образовательных конференций &quot;Неврологические образовательные университеты&quot; состоялась Научно-практическая конференция &quot;Дифференциальная диагностика и лечение демиелинизирующих заболеваний нервной системы и нейроинфекций&quot;. </p><h6 class="mt-3" data-v-d801f092>Научный руководитель конференции:</h6><p data-v-d801f092><strong data-v-d801f092>Владимир Иванович Шмырев</strong> — д.м.н., профессор, заведующий кафедрой неврологии ФГБУ «ЦГМА» УД Президента РФ, главный специалист по неврологии ГМУ УД Президента РФ. </p><h6 class="mt-3" data-v-d801f092>Научный секретарь конференции:</h6><p data-v-d801f092><strong data-v-d801f092>Алексей Сергеевич Васильев</strong> — к.м.н., доцент кафедры неврологии ФГБУ «ЦГМА» УД Президента РФ. </p><p class="mt-3" data-v-d801f092> С видеоархивом конференции можно ознакомиться по этой <a href="#" class="link-primary" data-v-d801f092>ссылке</a>. </p></div></div><h4 data-v-d801f092>Научные руководители:</h4><ul data-v-d801f092><li data-v-d801f092><strong data-v-d801f092>Владимир Иванович Шмырев</strong> — д.м.н., профессор, заведующий кафедрой неврологии ФГБУ &quot;ЦЛГМА&quot; УД Президента РФ, главный специалист по неврологии ГМУ УД Президента РФ. </li><li data-v-d801f092><strong data-v-d801f092>Алексей Сергеевич Васильев</strong> — к.м.н., доцент кафедры неврологии ФГБУ &quot;ЦЛГМА&quot; УД Президента РФ. </li></ul><div class="card my-5" data-v-d801f092><div class="card-body" data-v-d801f092><h5 class="card-title" data-v-d801f092>Провайдер конференции</h5><p class="card-text" data-v-d801f092><strong data-v-d801f092>ООО &quot;Медзнания&quot;</strong><br data-v-d801f092> 127083, г.Москва, Большой Каретный пер., 7<br data-v-d801f092> Телефон: (495) 699-14-65, 699-81-84<br data-v-d801f092> E-mail: <a href="mailto:info@medq.ru" data-v-d801f092>info@medq.ru</a></p></div></div>',12)]))}const u=d(r,[["render",o],["__scopeId","data-v-d801f092"]]);export{u as default};
